export const BODY: string = "\n<p>واٹر مارک تصویر پر آپ کا نام یا لوگو ہے، جو بتاتا ہے کہ تصویر کس کی ہے۔ اچھا واٹر مارک تصویر کی حفاظت کرتا ہے اور برا واٹر مارک تصویر کو خراب کرتا ہے۔</p>\n<p>واٹر مارک کی کامیابی جگہ، شفافیت، سائز اور رنگ پر منحصر ہے۔ ان چاروں کو درست کریں تو واٹر مارک نظر بھی آتا ہے اور تصویر بھی خراب نہیں ہوتی۔</p>\n<p>یہ رہنما بتاتا ہے کہ واٹر مارک کہاں لگائیں، کتنا نمایاں رکھیں، اور کون سی غلطیاں نہ کریں۔ واٹر مارک لگانے کے لیے <a href=\"/ur/tasveer-par-watermark-lagayein/\">امیج واٹر مارک</a> استعمال کریں۔</p>\n<h2 id=\"why-watermarks-fail\">واٹر مارک ناکام کیوں ہوتے ہیں</h2>\n<p>واٹر مارک اس وقت ناکام ہوتا ہے جب وہ بہت ہلکا ہو اور نظر نہ آئے، یا بہت گہرا ہو اور تصویر کو ڈھانپ دے۔ دونوں انتہائیں غلط ہیں۔</p>\n<p>واٹر مارک اس وقت بھی ناکام ہوتا ہے جب وہ کنارے پر ہو اور آسانی سے کاٹا جا سکے۔ کنارے کا واٹر مارک تصویر کو کراپ کر کے ہٹایا جا سکتا ہے۔</p>\n<p>واٹر مارک کی ناکامی کی تیسری وجہ یہ ہے کہ وہ ہر تصویر پر ایک جیسا لگایا جاتا ہے، بغیر تصویر کو دیکھے۔ ہر تصویر کو الگ جگہ چاہیے۔</p>\n<h2 id=\"placement-rules\">جگہ کے اصول</h2>\n<p>واٹر مارک کی سب سے محفوظ جگہ تصویر کے درمیان ہے، جہاں اسے کاٹا نہیں جا سکتا۔ لیکن درمیان کا واٹر مارک تصویر کو خراب کرتا ہے۔</p>\n<p>توازن یہ ہے کہ واٹر مارک کو تصویر کے اہم حصے کے قریب رکھیں، مگر اسے ڈھانپیں نہیں۔ کنارے سے دور، درمیان سے ہٹ کر۔</p>\n<p>جگہ چننے میں تصویر کو دیکھیں: سادہ حصے میں واٹر مارک زیادہ نمایاں ہوتا ہے، مصروف حصے میں کم۔ سادہ حصہ چنیں۔</p>\n<h2 id=\"opacity-rules\">شفافیت کے اصول</h2>\n<p>شفافیت 30 سے 50 فیصد کے درمیان رکھیں۔ اس حد میں واٹر مارک نظر آتا ہے مگر تصویر کو ڈھانپتا نہیں۔</p>\n<p>شفافیت تصویر پر منحصر ہے: ہلکی تصویر پر کم شفافیت، گہری تصویر پر زیادہ۔ ہر تصویر پر جانچیں۔</p>\n<p>شفافیت اتنی کم نہ رکھیں کہ واٹر مارک نظر نہ آئے۔ اگر وہ نظر نہ آئے تو اس کا کوئی فائدہ نہیں۔</p>\n<h2 id=\"size-rules\">سائز کے اصول</h2>\n<p>واٹر مارک کا سائز تصویر کے 10 سے 15 فیصد کے برابر رکھیں۔ اس سائز میں وہ پڑھا جاتا ہے مگر تصویر کو نہیں ڈھانپتا۔</p>\n<p>سائز تصویر کے سائز پر منحصر ہے: بڑی تصویر پر بڑا واٹر مارک، چھوٹی پر چھوٹا۔ تناسب ایک جیسا رکھیں۔</p>\n<p>سائز اتنا بڑا نہ رکھیں کہ وہ تصویر کا مرکز بن جائے۔ واٹر مارک معاون ہے، مرکزی نہیں۔</p>\n<h2 id=\"colour-and-contrast\">رنگ اور کنٹراسٹ</h2>\n<p>واٹر مارک کا رنگ تصویر کے برعکس چنیں۔ ہلکی تصویر پر گہرا واٹر مارک، گہری پر ہلکا۔</p>\n<p>سفید واٹر مارک سب سے زیادہ استعمال ہوتا ہے، کیونکہ وہ زیادہ تر تصویروں پر نظر آتا ہے۔ کالا دوسرا محفوظ انتخاب ہے۔</p>\n<p>رنگین واٹر مارک صرف اس وقت استعمال کریں جب وہ آپ کی برانڈ کا رنگ ہو۔ رنگین واٹر مارک تصویر سے ٹکراتا ہے۔</p>\n<h2 id=\"text-vs-logo\">متن بمقابلہ لوگو</h2>\n<p>متن والا واٹر مارک، جیسے آپ کا نام یا ویب سائٹ، پڑھا جا سکتا ہے اور برانڈ بناتا ہے۔ لوگو والا واٹر مارک زیادہ پیشہ ورانہ لگتا ہے۔</p>\n<p>لوگو اس وقت بہتر ہے جب آپ کا لوگو پہچانا جاتا ہو۔ متن اس وقت بہتر ہے جب آپ نئے ہوں اور نام بتانا چاہتے ہوں۔</p>\n<p>دونوں کا امتزاج بھی چلتا ہے: چھوٹا لوگو اور اس کے ساتھ نام۔ یہ سب سے مکمل واٹر مارک ہے۔</p>\n<h2 id=\"tiled-vs-single\">ٹائلڈ بمقابلہ واحد واٹر مارک</h2>\n<p>ٹائلڈ واٹر مارک پوری تصویر پر بار بار لگتا ہے، جیسے جالی۔ یہ ہٹانا سب سے مشکل ہے، کیونکہ ہر جگہ ہے۔</p>\n<p>واحد واٹر مارک صرف ایک جگہ لگتا ہے۔ یہ تصویر کو کم خراب کرتا ہے، مگر ہٹانا آسان ہے۔</p>\n<p>پروف کے لیے ٹائلڈ چنیں، حتمی تصویر کے لیے واحد۔ پروف میں حفاظت زیادہ اہم ہے، حتمی میں خوبصورتی۔</p>\n<h2 id=\"branding-consistency\">برانڈنگ میں یکسانیت</h2>\n<p>واٹر مارک ہر تصویر پر ایک جیسا ہونا چاہیے: ایک ہی جگہ، ایک ہی سائز، ایک ہی رنگ۔ یکسانیت برانڈ بناتی ہے۔</p>\n<p>یکسانیت سے لوگ آپ کی تصویر کو پہچاننے لگتے ہیں، بغیر نام پڑھے۔ یہ برانڈ کی طاقت ہے۔</p>\n<p>یکسانیت کے لیے واٹر مارک کا ٹیمپلیٹ بنائیں اور ہر تصویر پر وہی استعمال کریں۔</p>\n<h2 id=\"proofs-workflow\">پروف کا ورک فلو</h2>\n<p>پروف وہ تصویر ہے جو گاہک کو دکھائی جاتی ہے، حتمی خرید سے پہلے۔ پروف پر واٹر مارک مضبوط ہونا چاہیے، تاکہ گاہک اسے بغیر خریدے استعمال نہ کر سکے۔</p>\n<p>پروف کا واٹر مارک ٹائلڈ رکھیں، تاکہ وہ ہر جگہ ہو۔ حتمی تصویر پر واٹر مارک ہلکا یا نہ ہو۔</p>\n<p>پروف بھیجنے سے پہلے واٹر مارک جانچیں۔ اگر وہ کمزور ہو تو گاہک تصویر چوری کر سکتا ہے۔</p>\n<h2 id=\"social-media-marks\">سوشل میڈیا پر واٹر مارک</h2>\n<p>سوشل میڈیا پر واٹر مارک ضروری ہے، کیونکہ تصویر تیزی سے شیئر ہوتی ہے اور اصل بنانے والا بھول جاتا ہے۔</p>\n<p>سوشل میڈیا کا واٹر مارک چھوٹا اور کنارے پر رکھیں، تاکہ تصویر خوبصورت لگے۔ سوشل پر واٹر مارک حفاظت سے زیادہ برانڈنگ ہے۔</p>\n<p>سوشل میڈیا پر واٹر مارک میں ویب سائٹ کا پتہ شامل کریں، تاکہ لوگ آپ تک پہنچ سکیں۔</p>\n<h2 id=\"print-and-watermarks\">پرنٹ اور واٹر مارک</h2>\n<p>پرنٹ میں واٹر مارک اسکرین سے زیادہ نمایاں ہوتا ہے، کیونکہ پرنٹ میں رنگ گہرے ہوتے ہیں۔ پرنٹ کے لیے شفافیت کم رکھیں۔</p>\n<p>پرنٹ سے پہلے واٹر مارک کا نمونہ پرنٹ کر کے دیکھیں۔ اسکرین پر جو ہلکا لگتا ہے، وہ پرنٹ میں گہرا ہو سکتا ہے۔</p>\n<p>پرنٹ شاپ کے لیے واٹر مارک کی الگ فائل رکھیں، تاکہ حتمی پرنٹ پر واٹر مارک نہ ہو۔</p>\n<h2 id=\"watermark-and-copyright\">واٹر مارک اور کاپی رائٹ</h2>\n<p>واٹر مارک کاپی رائٹ کی جگہ نہیں لیتا، مگر اسے ثابت کرنے میں مدد کرتا ہے۔ واٹر مارک والی تصویر کا مالک پہچانا جاتا ہے۔</p>\n<p>واٹر مارک میں کاپی رائٹ کا سال اور نام شامل کریں، تاکہ ثبوت مضبوط ہو۔</p>\n<p>کاپی رائٹ کے لیے واٹر مارک کے ساتھ تصویر کا اصل بھی محفوظ رکھیں۔ اصل فائل سب سے مضبوط ثبوت ہے۔</p>\n<h2 id=\"testing-your-mark\">اپنے واٹر مارک کی جانچ</h2>\n<p>واٹر مارک کی جانچ کے لیے تصویر کو کسی اور کو دکھائیں۔ اگر وہ واٹر مارک پڑھ سکے اور تصویر بھی دیکھ سکے تو واٹر مارک درست ہے۔</p>\n<p>جانچ کے لیے تصویر کو چھوٹا کر کے دیکھیں۔ چھوٹی تصویر پر واٹر مارک اکثر غائب ہو جاتا ہے۔</p>\n<p>جانچ کے لیے تصویر کو کراپ کر کے دیکھیں۔ اگر واٹر مارک کراپ سے بچ جائے تو جگہ درست ہے۔</p>\n<h2 id=\"mistakes-to-avoid\">کون سی غلطیاں نہ کریں</h2>\n<p>سب سے بڑی غلطی بہت بڑا واٹر مارک ہے، جو تصویر کو ڈھانپ دیتا ہے۔ سائز چھوٹا رکھیں۔</p>\n<p>دوسری غلطی کنارے پر واٹر مارک ہے، جو کراپ سے ہٹ جاتا ہے۔ جگہ درمیان کے قریب رکھیں۔</p>\n<p>تیسری غلطی ہر تصویر پر مختلف واٹر مارک ہے۔ یکسانیت رکھیں، تاکہ برانڈ بنے۔</p>\n<h2 id=\"watermark-habit\">واٹر مارک کی عادت</h2>\n<p>واٹر مارک کی عادت بنائیں: ہر تصویر شائع کرنے سے پہلے واٹر مارک لگائیں۔ عادت بن جائے تو کوئی تصویر بغیر واٹر مارک کے نہیں جاتی۔</p>\n<p>عادت کے لیے ٹیمپلیٹ بنائیں، تاکہ واٹر مارک لگانا سیکنڈوں کا کام ہو۔</p>\n<p>عادت کی جانچ یہ ہے کہ آپ کی پرانی تصویریں بھی واٹر مارک والی ہوں۔ اگر کوئی بغیر واٹر مارک کے ہو تو اسے بھی لگائیں۔</p>\n<h2 id=\"watermarking-for-print-shops\">پرنٹ شاپ کے لیے واٹر مارک</h2>\n<p>پرنٹ شاپ کو واٹر مارک والی تصویر نہ بھیجیں، کیونکہ وہ پرنٹ میں آ جائے گا۔ پرنٹ شاپ کو صاف تصویر بھیجیں۔</p>\n<p>پرنٹ شاپ کے لیے واٹر مارک صرف پروف میں رکھیں، حتمی فائل میں نہیں۔ پروف اور حتمی فائل الگ رکھیں۔</p>\n<p>پرنٹ شاپ سے کہیں کہ وہ واٹر مارک والی فائل کو پرنٹ نہ کرے۔ صاف فائل کا نام الگ رکھیں، تاکہ غلطی نہ ہو۔ مزید تفصیل <a href=\"/ur/blog/tasveer-watermark-rehnumai/\">واٹر مارک گائیڈ</a> میں اور متن شامل کرنے کے طریقے <a href=\"/ur/blog/tasveer-par-watermark-kaise-lagayein/\">واٹر مارک کیسے لگائیں</a> میں دیکھیں۔</p>\n";

